1	// Command relayproof is the 跨链消息与轻客户端验证服务 entry point.
2	package main
3	
4	import (
5		"fmt"
6		"os"
7		"strings"
8	
9		"github.com/asdhoaiqqq/relayproof-bridge/relayproof"
10	)
11	
12	// sourceCIDRFlag is the sole normalize option: an IPv4 network that restricts
13	// which successful events are emitted.
14	const sourceCIDRFlag = "--source-cidr"
15	
16	func main() {
17		command := "demo"
18		if len(os.Args) > 1 {
19			command = os.Args[1]
20		}
21		switch command {
22		case "demo":
23			runDemo()
24		case "normalize":
25			runNormalize()
26		case "version":
27			fmt.Println("relayproof 0.1.0")
28		case "help", "-h", "--help":
29			usage()
30		default:
31			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
32			usage()
33			os.Exit(2)
34		}
35	}
36	
37	func usage() {
38		fmt.Println("usage: relayproof [demo|normalize|version|help]")
39		fmt.Println()
40		fmt.Println("  demo       run the built-in verification demo (default with no arguments)")
41		fmt.Println("  normalize   read newline-delimited JSON logs from stdin and write")
42		fmt.Println("              normalized event results to stdout, one JSON object per line;")
43		fmt.Println("              exits non-zero when one or more input lines fail")
44		fmt.Println()
45		fmt.Println("              options:")
46		fmt.Println("                --source-cidr <IPv4>/<prefix>")
47		fmt.Println("                    emit a successful event only when its normalized")
48		fmt.Println("                    source_ip lies in this single IPv4 network (prefix")
49		fmt.Println(`                    length 0-32, e.g. "192.0.2.0/24" or "192.0.2.123/24";`)
50		fmt.Println("                    failed lines are still reported. May be given once.")
51		fmt.Println("  version     print the relayproof version")
52		fmt.Println("  help        show this help")
53	}
54	
55	func runNormalize() {
56		// Options are parsed before stdin is read: a malformed option exits 2
57		// with empty stdout, exactly like a stream-level failure, and no log
58		// content is consumed or produced for it.
59		filter, err := parseNormalizeOptions(os.Args[2:])
60		if err != nil {
61			fmt.Fprintf(os.Stderr, "normalize: %v\n", err)
62			os.Exit(2)
63		}
64		failures, err := relayproof.NormalizeReaderFiltered(os.Stdin, os.Stdout, filter)
65		if err != nil {
66			fmt.Fprintf(os.Stderr, "normalize: %v\n", err)
67			os.Exit(2)
68		}
69		if failures > 0 {
70			os.Exit(1)
71		}
72	}
73	
74	// parseNormalizeOptions accepts at most one --source-cidr option, in either
75	// "--source-cidr value" or "--source-cidr=value" form. A missing or empty
76	// value, a value outside the IPv4/prefix grammar, a repeated option, or any
77	// other argument is a parameter error: the caller reports it on stderr and
78	// exits 2 before opening the log stream.
79	func parseNormalizeOptions(args []string) (*relayproof.SourceCIDRFilter, error) {
80		var filter *relayproof.SourceCIDRFilter
81		specified := false
82		for i := 0; i < len(args); i++ {
83			arg := args[i]
84			switch {
85			case arg == sourceCIDRFlag:
86				if specified {
87					return nil, fmt.Errorf("%s may be specified at most once", sourceCIDRFlag)
88				}
89				if i+1 >= len(args) {
90					return nil, fmt.Errorf("%s requires a value: an IPv4 network in dotted decimal with a \"/0\" to \"/32\" prefix length, e.g. %q",
91						sourceCIDRFlag, "192.0.2.0/24")
92				}
93				i++
94				value := args[i]
95				parsed, err := relayproof.ParseSourceCIDRFilter(value)
96				if err != nil {
97					return nil, fmt.Errorf("invalid %s value: %w", sourceCIDRFlag, err)
98				}
99				filter, specified = &parsed, true
100			case strings.HasPrefix(arg, sourceCIDRFlag+"="):
101				if specified {
102					return nil, fmt.Errorf("%s may be specified at most once", sourceCIDRFlag)
103				}
104				value := strings.TrimPrefix(arg, sourceCIDRFlag+"=")
105				parsed, err := relayproof.ParseSourceCIDRFilter(value)
106				if err != nil {
107					return nil, fmt.Errorf("invalid %s value: %w", sourceCIDRFlag, err)
108				}
109				filter, specified = &parsed, true
110			default:
111				return nil, fmt.Errorf("unknown argument %q; normalize accepts only %s <IPv4>/<prefix>", arg, sourceCIDRFlag)
112			}
113		}
114		return filter, nil
115	}
116	
117	func runDemo() {
118		headers := map[string]relayproof.Header{
119			"chain-a": {Chain: "chain-a", Height: 1024, Root: "0xabc", Trusted: true},
120		}
121		consumed := map[string]bool{}
122		messages := []relayproof.Message{
123			{ID: "msg-1", From: "chain-a", To: "chain-b", Nonce: 7, ProofAt: 1000},
124			{ID: "msg-2", From: "chain-c", To: "chain-b", Nonce: 1, ProofAt: 10},
125		}
126		for _, message := range messages {
127			delivery := relayproof.Verify(headers, message, consumed)
128			fmt.Printf("message=%s status=%s reason=%s\n", delivery.Message, delivery.Status, delivery.Reason)
129		}
130		replay := relayproof.Verify(headers, messages[0], consumed)
131		fmt.Printf("replay of %s status=%s reason=%s\n", replay.Message, replay.Status, replay.Reason)
132		fmt.Println("pending:", relayproof.Pending(headers, messages))
133	}
