1	package main
2	
3	// CLI-level regression coverage for character corruption under the
4	// normalize --source-cidr filter. The filter may only omit successful
5	// out-of-network events; it must never let a corrupted log vanish. With
6	// 192.0.2.0/24 selected, a line sourced from 198.51.100.9 — or carrying no
7	// source address at all — still fails when an unknown field's string (or a
8	// string nested in its objects and arrays) holds invalid UTF-8 bytes or an
9	// unpaired \uXXXX surrogate escape: one ok:false record with the original
10	// physical line number and a single error, no event. The two corruption
11	// classes stay distinguishable, precedence between competing problems is
12	// exactly the unfiltered run's, failure records sit among dropped valid
13	// lines, blank lines and later hits without renumbering, the process exits
14	// 1 with stderr empty, and legal lookalikes (paired escapes, escaped
15	// backslash before uD800) are never flagged.
16	
17	import (
18		"bytes"
19		"strings"
20		"testing"
21		"unicode/utf8"
22	)
23	
24	// A mixed stream under --source-cidr 192.0.2.0/24: corrupted out-of-network
25	// and source-less logs interleaved with a valid out-of-network log, a blank
26	// line and in-network hits. The corrupted lines keep their failure records
27	// with physical line numbers and their own error class, the valid
28	// out-of-network log produces no record and no failure, the blank line only
29	// consumes a line number, and the hits come out in input order. Exit status
30	// is 1, stderr stays empty, and the per-line reasons live only in the
31	// stdout records.
32	func TestNormalizeCLISourceCIDRCorruptionStillReported(t *testing.T) {
33		input := []byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"hit-1","source_ip":"192.0.2.7"}` + "\n" +
34			// Line 2: unpaired escape in an unknown field's nested array, source out of network.
35			`{"timestamp":"2026-01-02T00:00:00Z","action":"x","source_ip":"198.51.100.9","meta":{"list":["ok","\uD800"]}}` + "\n" +
36			// Line 3: valid but out of network — no record, no failure.
37			`{"timestamp":"2026-01-02T00:00:00Z","action":"outside","source_ip":"198.51.100.1"}` + "\n" +
38			"\n" +
39			// Line 5: invalid UTF-8 byte in an unknown field, no source address.
40			`{"timestamp":"2026-01-02T00:00:00Z","action":"y","note":"` + "\xff" + `"}` + "\n" +
41			`{"timestamp":"2026-01-02T00:00:00Z","action":"hit-2","source_ip":"192.0.2.8"}` + "\n")
42	
43		result := runNormalizeCLIArgs(t, bytes.NewReader(input), "--source-cidr", "192.0.2.0/24")
44	
45		if result.exitCode != 1 {
46			t.Fatalf("corrupted lines must set exit status 1 even though their sources are filtered out, got %d (stderr: %q)", result.exitCode, result.stderr)
47		}
48		if result.stderr != "" {
49			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
50		}
51		if !utf8.ValidString(result.stdout) {
52			t.Fatalf("stdout must be valid UTF-8 even for corrupted input, got %q", result.stdout)
53		}
54		if strings.Contains(result.stdout, "�") {
55			t.Fatalf("corrupted input must not be rewritten with replacement characters: %q", result.stdout)
56		}
57	
58		results := decodeStdoutResults(t, result.stdout)
59		if len(results) != 4 {
60			t.Fatalf("expected 2 hits + 2 failures; the valid out-of-network log and the blank line produce nothing, got %#v", results)
61		}
62	
63		wantLines := []float64{1, 2, 5, 6}
64		for i, line := range wantLines {
65			if results[i]["line"] != line {
66				t.Fatalf("record %d must carry physical line %v: %#v", i, line, results[i])
67			}
68		}
69	
70		if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "hit-1" {
71			t.Fatalf("the leading in-network hit must survive on line 1: %#v", results[0])
72		}
73	
74		// Each failure record is exactly line, ok:false and one error — no event.
75		failures := []struct {
76			index    int
77			contains []string
78			excludes []string
79		}{
80			{1, []string{"unpaired", "surrogate"}, []string{"UTF-8"}},
81			{2, []string{"UTF-8"}, []string{"surrogate"}},
82		}
83		for _, f := range failures {
84			r := results[f.index]
85			if r["ok"] != false {
86				t.Fatalf("record %d must be a failure: %#v", f.index, r)
87			}
88			if _, exists := r["event"]; exists {
89				t.Fatalf("a failed line must not carry an event: %#v", r)
90			}
91			if len(r) != 3 {
92				t.Fatalf("a failure record carries exactly line, ok and one error, got %#v", r)
93			}
94			msg, _ := r["error"].(string)
95			if msg == "" {
96				t.Fatalf("a failed line must explain itself: %#v", r)
97			}
98			for _, marker := range f.contains {
99				if !strings.Contains(msg, marker) {
100					t.Fatalf("record %d error %q must contain %q", f.index, msg, marker)
101				}
102			}
103			for _, marker := range f.excludes {
104				if strings.Contains(msg, marker) {
105					t.Fatalf("record %d error %q must not contain %q", f.index, msg, marker)
106				}
107			}
108		}
109	
110		if results[3]["ok"] != true || eventOf(t, results[3])["action"] != "hit-2" {
111			t.Fatalf("the trailing in-network hit must survive on line 6: %#v", results[3])
112		}
113	}
114	
115	// The filter must not change which problem a corrupted line reports: an
116	// unpaired escape earlier in the text than an invalid UTF-8 byte still loses
117	// to the byte encoding problem, and an unpaired escape in an unknown field
118	// still outranks an invalid timestamp. Each line's error under the filter is
119	// byte-for-byte the error the unfiltered run reports.
120	func TestNormalizeCLISourceCIDRKeepsCharsetPrecedence(t *testing.T) {
121		lines := []string{
122			// Unpaired escape first, invalid byte later: position must not let
123			// the escape win.
124			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","source_ip":"198.51.100.9","note":"\uD800` + "\xff" + `"}`,
125			// Legal bytes, unpaired escape in an unknown field, invalid
126			// timestamp: the escape is reported, not the time.
127			`{"timestamp":"not-a-time","action":"a","source_ip":"198.51.100.9","note":"\uD800"}`,
128		}
129		markers := []struct {
130			contains []string
131			excludes []string
132		}{
133			{[]string{"UTF-8"}, []string{"surrogate", "escape"}},
134			{[]string{"unpaired", "surrogate"}, []string{"UTF-8", "timestamp"}},
135		}
136	
137		for i, line := range lines {
138			filtered := runNormalizeCLIArgs(t, strings.NewReader(line+"\n"), "--source-cidr", "192.0.2.0/24")
139			unfiltered := runNormalizeCLI(t, strings.NewReader(line+"\n"))
140	
141			if filtered.exitCode != 1 || unfiltered.exitCode != 1 {
142				t.Fatalf("line %d must exit 1 with and without the filter, got %d and %d", i+1, filtered.exitCode, unfiltered.exitCode)
143			}
144			if filtered.stderr != "" || unfiltered.stderr != "" {
145				t.Fatalf("line %d reasons belong in stdout records, got stderr %q / %q", i+1, filtered.stderr, unfiltered.stderr)
146			}
147	
148			filteredResults := decodeStdoutResults(t, filtered.stdout)
149			unfilteredResults := decodeStdoutResults(t, unfiltered.stdout)
150			if len(filteredResults) != 1 || len(unfilteredResults) != 1 {
151				t.Fatalf("line %d must produce exactly one failure record in both runs: %#v / %#v", i+1, filteredResults, unfilteredResults)
152			}
153			filteredMsg, _ := filteredResults[0]["error"].(string)
154			unfilteredMsg, _ := unfilteredResults[0]["error"].(string)
155			if filteredMsg == "" || filteredMsg != unfilteredMsg {
156				t.Fatalf("line %d error must be identical with and without the filter:\nfiltered:   %q\nunfiltered: %q", i+1, filteredMsg, unfilteredMsg)
157			}
158			for _, marker := range markers[i].contains {
159				if !strings.Contains(filteredMsg, marker) {
160					t.Fatalf("line %d error %q must contain %q", i+1, filteredMsg, marker)
161				}
162			}
163			for _, marker := range markers[i].excludes {
164				if strings.Contains(filteredMsg, marker) {
165					t.Fatalf("line %d error %q must not contain %q", i+1, filteredMsg, marker)
166				}
167			}
168		}
169	}
170	
171	// Legal lookalikes are never flagged as corruption, and the filter still
172	// decides purely by network: an in-network log carrying a correctly paired
173	// surrogate escape and the plain text "uD800" behind an escaped backslash is
174	// emitted with its string meanings intact, while an all-valid batch whose
175	// sources all miss the network ends with empty stdout and exit status 0.
176	func TestNormalizeCLISourceCIDRLegalLookalikesFilteredByNetworkOnly(t *testing.T) {
177		inNetwork := `{"timestamp":"2026-01-02T00:00:00Z","action":"login","source_ip":"192.0.2.7",` +
178			`"pair":"😀","note":"\\uD800"}`
179		outOfNetwork := `{"timestamp":"2026-01-02T00:00:00Z","action":"other","source_ip":"198.51.100.9",` +
