181	
182		hit := runNormalizeCLIArgs(t, strings.NewReader(inNetwork+"\n"), "--source-cidr", "192.0.2.0/24")
183		if hit.exitCode != 0 || hit.stderr != "" {
184			t.Fatalf("a legal in-network log must exit 0 with empty stderr, got %d / %q", hit.exitCode, hit.stderr)
185		}
186		results := decodeStdoutResults(t, hit.stdout)
187		if len(results) != 1 || results[0]["ok"] != true {
188			t.Fatalf("legal lookalikes from inside the network must be admitted, got %#v", results)
189		}
190		extra, ok := eventOf(t, results[0])["extra"].(map[string]any)
191		if !ok {
192			t.Fatalf("the unknown fields must land in extra: %#v", results[0])
193		}
194		if extra["pair"] != "😀" {
195			t.Fatalf("the paired escape must decode to the emoji, got %v", extra["pair"])
196		}
197		if extra["note"] != `\uD800` {
198			t.Fatalf(`escaped-backslash text must stay the plain text \uD800, got %v`, extra["note"])
199		}
200	
201		allFiltered := runNormalizeCLIArgs(t, strings.NewReader(outOfNetwork+"\n"+outOfNetwork+"\n"),
202			"--source-cidr", "192.0.2.0/24")
203		if allFiltered.exitCode != 0 {
204			t.Fatalf("an all-valid batch that misses the network must exit 0, got %d (stderr: %q)", allFiltered.exitCode, allFiltered.stderr)
205		}
206		if allFiltered.stdout != "" || allFiltered.stderr != "" {
207			t.Fatalf("no surviving records means empty stdout/stderr, got %q / %q", allFiltered.stdout, allFiltered.stderr)
208		}
209	}
