				// and members moved ahead of the companions.
				orderings := []string{
					cliDualOrdered(ts, canon, alias, act),
					cliDualOrdered(ts, alias, canon, act),
					cliDualOrdered(act, canon, ts, alias),
					cliDualOrdered(alias, act, ts, canon),
