		{1, true, "lead-in"},
		{2, true, "x"},
		{4, false, "conflicting values"},
		{5, false, "conflicting values"},
		{6, false, "conflicting values"},
		{7, false, "invalid IP address"},
		{8, false, "got null"},
		{12, true, "tail-in"},
	}
